custom_css:
/* ===== Fundación CDMC · capa de marca ===== */
.banner{position:relative;margin:0 0 clamp(3rem,7vw,5.5rem);border-radius:var(--r-xl);overflow:hidden;aspect-ratio:16/8;border:1px solid var(--border-strong);box-shadow:var(--shadow-lg)}
.banner img{width:100%;height:124%;object-fit:cover;object-position:center 35%;filter:saturate(.9) contrast(1.05)}
.banner::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgb(var(--bg-rgb)/.15) 30%,rgb(var(--bg-rgb)/.88) 100%),linear-gradient(100deg,rgb(var(--glow-rgb)/.28),transparent 55%);pointer-events:none}
.banner figcaption{position:absolute;z-index:2;left:clamp(1rem,3vw,2rem);bottom:clamp(1rem,3vw,1.8rem);display:inline-flex;align-items:center;gap:.7rem;font:600 .8rem/1 var(--font-display);letter-spacing:.16em;text-transform:uppercase;color:var(--text)}
.banner__dot{width:.6rem;height:.6rem;border-radius:50%;background:var(--glow);animation:dotPulse 1.8s ease-out infinite}
.brig{display:grid;gap:clamp(2.2rem,5vw,4rem)}
.brig__copy .lead{margin:1.2rem 0 2rem;max-width:34rem}
.pillars__t{font:600 .78rem/1 var(--font-display);letter-spacing:.2em;text-transform:uppercase;color:var(--muted);margin-bottom:1.2rem}
.pillars ul{display:grid;gap:.9rem;grid-template-columns:1fr}
.pillar{position:relative;padding:1.3rem 1.4rem 1.3rem 4.4rem;border-radius:var(--r-lg);background:var(--surface);border:1px solid var(--border);transition:border-color .5s,transform .6s var(--ease),box-shadow .6s var(--ease)}
.pillar:hover{border-color:rgb(var(--glow-rgb)/.5);transform:translateY(-4px);box-shadow:var(--shadow-lg)}
.pillar span{position:absolute;left:1.3rem;top:1.25rem;font:800 1.5rem/1 var(--font-display);letter-spacing:-.04em;background:linear-gradient(135deg,var(--primary-ink),var(--accent-ink));-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent}
.pillar h3{font-size:1.08rem;margin-bottom:.25rem}
.pillar p{color:var(--muted);font-size:.93rem;line-height:1.5}
.courses{display:grid;gap:clamp(2rem,5vw,3.5rem)}
.course{display:grid;border-radius:var(--r-xl);background:var(--surface);border:1px solid var(--border);overflow:hidden;box-shadow:var(--shadow-lg)}
.course__media{position:relative;min-height:17rem;overflow:hidden;background:var(--bg-2)}
.course__media img{position:absolute;inset:-12% 0;width:100%;height:124%;object-fit:cover;filter:saturate(.92) contrast(1.04)}
.course__media::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,rgb(11 8 9/.55)),linear-gradient(120deg,rgb(var(--glow-rgb)/.22),transparent 60%);pointer-events:none}
.course__tag{position:absolute;z-index:2;left:1.1rem;top:1.1rem;padding:.5rem .95rem;border-radius:99px;font:700 .72rem/1 var(--font-display);letter-spacing:.16em;text-transform:uppercase;color:#fff;background:rgb(11 8 9/.55);border:1px solid rgb(255 255 255/.25);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
.course__body{padding:clamp(1.5rem,4vw,3rem)}
.course__body h3{font-size:clamp(1.6rem,2.4vw + .8rem,2.4rem);letter-spacing:-.03em;margin-bottom:.8rem}
.course__obj{color:var(--muted);font-size:1.02rem;margin-bottom:1.6rem}
.course__body h4{font:700 .74rem/1 var(--font-display);letter-spacing:.18em;text-transform:uppercase;color:var(--primary-ink);margin:1.6rem 0 .9rem}
.temario{display:grid;gap:.55rem .9rem;counter-reset:t;grid-template-columns:1fr}
.temario li{counter-increment:t;display:flex;align-items:center;gap:.75rem;padding:.6rem .85rem;border-radius:.8rem;background:var(--bg-2);border:1px solid var(--border);font-size:.92rem;line-height:1.35;transition:border-color .4s,transform .4s var(--ease)}
.temario li::before{content:counter(t,decimal-leading-zero);flex:none;font:700 .74rem/1 var(--font-display);color:var(--primary-ink)}
.temario li:hover{border-color:rgb(var(--glow-rgb)/.5);transform:translateX(4px)}
.certs{display:flex;flex-wrap:wrap;gap:.6rem;margin-bottom:1.8rem}
.certs li{padding:.5rem .95rem;border-radius:99px;font:600 .82rem/1 var(--font-display);color:var(--primary-ink);background:rgb(var(--glow-rgb)/.09);border:1px solid rgb(var(--glow-rgb)/.28)}
.course .btn{max-width:100%;white-space:normal;text-align:center;padding-block:.9rem;height:auto}
.sec--brigadas{overflow:hidden}
.sec--brigadas::before{content:"";position:absolute;inset:0;background:radial-gradient(60% 50% at 85% 10%,rgb(var(--glow-rgb)/.22),transparent 70%),radial-gradient(50% 40% at 5% 90%,rgb(var(--glow2-rgb)/.14),transparent 70%);pointer-events:none}
.sec--brigadas .container{position:relative}
@media(min-width:860px){.brig{grid-template-columns:1fr 1.15fr;align-items:start}.pillars ul{grid-template-columns:1fr 1fr}.course{grid-template-columns:.85fr 1.15fr}.course--rev{grid-template-columns:1.15fr .85fr}.course--rev .course__media{order:2}.course__media{min-height:100%}.temario{grid-template-columns:1fr 1fr}}
